def max_k(N):
    max_val = 0
    for na in range(N + 1):
        for nb in range(N + 1):
            if (na == N and nb == 0) or (na == 0 and nb == N):
                continue
            k = N * (na + nb) - 2 * na * nb
            if k > max_val:
                max_val = k
    return max_val

print(max_k(64))

